import csv
def transform(source, destination):
    rows = []
    with open(source,newline="",encoding="utf-8") as handle:
        for row in csv.DictReader(handle):
            rows.append({"name":row["name"],"doubled":int(row["score"])*2})
    with open(destination,"w",newline="",encoding="utf-8") as handle:
        writer = csv.DictWriter(handle,fieldnames=["name","doubled"])
        writer.writeheader()
        for row in rows:
            writer.writerow(row)
    return len(rows)
